*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --color-bg:          #0f1117;
  --color-surface:     #1a1d27;
  --color-surface-2:   #23263a;
  --color-border:      #2e3150;
  --color-text:        #e8eaf6;
  --color-text-muted:  #8b90b8;
  --color-accent:      #7c6eff;
  --color-accent-h:    #6358e0;
  --color-danger:      #e05c5c;
  --color-danger-h:    #c94d4d;
  --color-danger-ring: rgba(224, 92, 92, .35);
  --color-white:       #ffffff;
  --radius-md:         10px;
  --radius-lg:         16px;
  --shadow-dialog:     0 24px 64px rgba(0,0,0,.6);
  --transition:        180ms ease;
}

/* ── Visually hidden (screen-reader only) ────────────────────────── */
.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* ── Skip link ───────────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  z-index: 9999;
  padding: .5rem 1rem;
  background: var(--color-accent);
  color: var(--color-white);
  border-radius: var(--radius-md);
  font-size: .875rem;
  font-weight: 600;
  text-decoration: none;
  transition: top var(--transition);
}
.skip-link:focus { top: 1rem; }

/* ── Base ────────────────────────────────────────────────────────── */
html { font-size: 16px; }

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background: var(--color-bg);
  color: var(--color-text);
  min-height: 100dvh;
  display: flex;
  flex-direction: column;
  line-height: 1.5;
}

/* ── Header ──────────────────────────────────────────────────────── */
.site-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1rem 2rem;
  border-bottom: 1px solid var(--color-border);
  background: var(--color-surface);
}

.logo {
  display: flex;
  align-items: center;
  gap: .5rem;
  font-weight: 700;
  font-size: 1.1rem;
  letter-spacing: -.01em;
  color: var(--color-text);
  text-decoration: none;
}

.logo svg { flex-shrink: 0; }

.nav-list {
  list-style: none;
  display: flex;
  gap: .25rem;
}

.nav-link {
  display: block;
  padding: .4rem .8rem;
  border-radius: var(--radius-md);
  color: var(--color-text-muted);
  text-decoration: none;
  font-size: .875rem;
  transition: color var(--transition), background var(--transition);
}

.nav-link:hover,
.nav-link:focus-visible {
  color: var(--color-text);
  background: var(--color-surface-2);
}

.nav-link[aria-current="page"] {
  color: var(--color-text);
  background: var(--color-surface-2);
}

/* ── Main layout ─────────────────────────────────────────────────── */
main {
  flex: 1;
  padding: 2.5rem 2rem 4rem;
  max-width: 900px;
  margin: 0 auto;
  width: 100%;
}

/* ── Breadcrumb ──────────────────────────────────────────────────── */
.breadcrumb {
  display: flex;
  align-items: center;
  gap: .5rem;
  font-size: .8125rem;
  color: var(--color-text-muted);
  margin-bottom: 1.75rem;
  flex-wrap: wrap;
}

.breadcrumb a {
  color: var(--color-text-muted);
  text-decoration: none;
  transition: color var(--transition);
}

.breadcrumb a:hover,
.breadcrumb a:focus-visible { color: var(--color-text); }

.breadcrumb-sep { opacity: .4; }

.breadcrumb [aria-current="page"] { color: var(--color-text); }

/* ── Page heading ────────────────────────────────────────────────── */
.page-heading {
  font-size: 1.625rem;
  font-weight: 700;
  letter-spacing: -.02em;
  margin-bottom: 1.75rem;
  line-height: 1.25;
}

/* ── Image card ──────────────────────────────────────────────────── */
.image-card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
}

.image-preview {
  position: relative;
  background: var(--color-surface-2);
  aspect-ratio: 16 / 9;
  overflow: hidden;
}

.image-preview img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.image-badge {
  position: absolute;
  top: .75rem;
  left: .75rem;
  background: rgba(0,0,0,.55);
  backdrop-filter: blur(6px);
  color: var(--color-white);
  font-size: .75rem;
  font-weight: 600;
  letter-spacing: .04em;
  text-transform: uppercase;
  padding: .25rem .6rem;
  border-radius: 6px;
  border: 1px solid rgba(255,255,255,.12);
}

/* ── Image meta ──────────────────────────────────────────────────── */
.image-meta {
  padding: 1.25rem 1.5rem 1.5rem;
}

.meta-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 1rem;
}

.meta-title {
  font-size: 1.125rem;
  font-weight: 600;
  letter-spacing: -.01em;
}

.meta-subtitle {
  font-size: .8125rem;
  color: var(--color-text-muted);
  margin-top: .2rem;
}

.meta-stats {
  display: flex;
  gap: 1rem;
  flex-shrink: 0;
}

.stat {
  text-align: right;
  font-size: .8125rem;
}

.stat-value {
  font-weight: 600;
  color: var(--color-text);
  display: block;
}

.stat-label {
  color: var(--color-text-muted);
  font-size: .75rem;
}

/* ── Divider ─────────────────────────────────────────────────────── */
.meta-divider {
  border: none;
  border-top: 1px solid var(--color-border);
  margin-bottom: 1.25rem;
}

/* ── Action row ──────────────────────────────────────────────────── */
.action-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: .75rem;
  flex-wrap: wrap;
}

.action-group {
  display: flex;
  align-items: center;
  gap: .5rem;
}

/* ── Buttons ─────────────────────────────────────────────────────── */
.btn {
  display: inline-flex;
  align-items: center;
  gap: .4rem;
  padding: .5rem 1rem;
  border-radius: var(--radius-md);
  font-size: .875rem;
  font-weight: 500;
  cursor: pointer;
  border: 1px solid transparent;
  transition: background var(--transition), color var(--transition),
              border-color var(--transition), box-shadow var(--transition);
  line-height: 1;
  white-space: nowrap;
}

.btn:focus-visible {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

.btn-ghost {
  background: transparent;
  border-color: var(--color-border);
  color: var(--color-text-muted);
}

.btn-ghost:hover {
  background: var(--color-surface-2);
  color: var(--color-text);
  border-color: var(--color-text-muted);
}

.btn-primary {
  background: var(--color-accent);
  color: var(--color-white);
}

.btn-primary:hover { background: var(--color-accent-h); }

.btn-danger {
  background: transparent;
  border-color: var(--color-danger);
  color: var(--color-danger);
}

.btn-danger:hover {
  background: var(--color-danger);
  color: var(--color-white);
}

.btn-danger:focus-visible {
  outline-color: var(--color-danger);
}

/* ── Dialog backdrop ─────────────────────────────────────────────── */
dialog::backdrop {
  background: rgba(0, 0, 0, .72);
  backdrop-filter: blur(4px);
}

/* ── Dialog ──────────────────────────────────────────────────────── */
dialog {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
