dialog {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-dialog);
  color: var(--color-text);
  padding: 0;
  width: min(440px, calc(100vw - 2rem));
  max-height: calc(100dvh - 4rem);
  overflow-y: auto;

