  background: var(--color-surface-2);
  aspect-ratio: 16 / 9;
  overflow: hidden;
}

.image-preview img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.image-badge {
  position: absolute;
  top: .75rem;
  left: .75rem;
  background: rgba(0,0,0,.55);
  backdrop-filter: blur(6px);
  color: var(--color-white);
  font-size: .75rem;
  font-weight: 600;
  letter-spacing: .04em;
  text-transform: uppercase;
  padding: .25rem .6rem;
  border-radius: 6px;
  border: 1px solid rgba(255,255,255,.12);
}

/* ── Image meta ──────────────────────────────────────────────────── */
.image-meta {
  padding: 1.25rem 1.5rem 1.5rem;
}

.meta-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 1rem;
}

.meta-title {
  font-size: 1.125rem;
  font-weight: 600;
  letter-spacing: -.01em;
}

.meta-subtitle {
  font-size: .8125rem;
  color: var(--color-text-muted);
  margin-top: .2rem;
}

.meta-stats {
  display: flex;
  gap: 1rem;
  flex-shrink: 0;
}

.stat {
  text-align: right;
  font-size: .8125rem;
}

.stat-value {
  font-weight: 600;
  color: var(--color-text);
  display: block;
}

.stat-label {
  color: var(--color-text-muted);
  font-size: .75rem;
}

/* ── Divider ─────────────────────────────────────────────────────── */
.meta-divider {
  border: none;
  border-top: 1px solid var(--color-border);
  margin-bottom: 1.25rem;
}

/* ── Action row ──────────────────────────────────────────────────── */
.action-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: .75rem;
  flex-wrap: wrap;
}

.action-group {
  display: flex;
  align-items: center;
  gap: .5rem;
