dialog {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-dialog);
  color: var(--color-text);
  padding: 0;
  width: min(440px, calc(100vw - 2rem));
  max-height: calc(100dvh - 4rem);
  overflow-y: auto;

  /* Slide-in only — no opacity fade so contrast is never degraded during animation */
  translate: 0 14px;
  transition: translate var(--transition),
              display var(--transition) allow-discrete,
              overlay var(--transition) allow-discrete;
}

dialog[open] {
  translate: 0 0;
}

@starting-style {
  dialog[open] {
    translate: 0 14px;
  }
}

.dialog-inner {
  padding: 1.75rem;
}

/* ── Dialog icon ─────────────────────────────────────────────────── */
.dialog-icon {
  width: 48px;
  height: 48px;
  border-radius: 12px;
  background: rgba(224, 92, 92, .12);
  border: 1px solid rgba(224, 92, 92, .25);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.25rem;
  color: var(--color-danger);
}

/* ── Dialog content ──────────────────────────────────────────────── */
.dialog-title {
  font-size: 1.1rem;
  font-weight: 700;
  letter-spacing: -.01em;
  margin-bottom: .5rem;
}

.dialog-body {
  font-size: .9rem;
  color: var(--color-text-muted);
  line-height: 1.6;
  margin-bottom: .25rem;
}

.dialog-image-name {
  font-size: .85rem;
  color: var(--color-text);
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
  border-radius: 6px;
  padding: .5rem .75rem;
  margin: .875rem 0 1.5rem;
  display: flex;
  align-items: center;
  gap: .5rem;
}

.dialog-image-name svg { flex-shrink: 0; color: var(--color-text-muted); }

/* ── Dialog actions ──────────────────────────────────────────────── */
.dialog-actions {
  display: flex;
  gap: .625rem;
  justify-content: flex-end;
}

.btn-dialog-cancel {
  background: var(--color-surface-2);
  border-color: var(--color-border);
  color: var(--color-text);
}

.btn-dialog-cancel:hover {
